using System.Text.Json;

namespace SixActual.Sim.Battle;

/// <summary>Global tuning read from data/rules.json (generated by scripts/generate_rules.py).</summary>
public sealed class BattleRules
{
    public int LosStepM { get; init; }

    public int EyeHeightDm { get; init; }

    public int TargetHeightDm { get; init; }

    public int ForestHeightDm { get; init; }

    public int ForestBlockPctM { get; init; }

    public int SmokeHeightDm { get; init; }

    public int HedgeHeightDm { get; init; }

    public int StealthForestBonus { get; init; }

    public int StealthMovingPenalty { get; init; }

    public int FiringRevealM { get; init; }

    public int RevealTicks { get; init; }

    public int SpotIntervalTicks { get; init; } = 1;

    public IReadOnlyDictionary<string, int> WeatherOpticsPct { get; init; } = new Dictionary<string, int>();

    /// <summary>SIM-11: hit-chance multiplier and air-operations flag per weather (by WeatherNames index).</summary>
    public int[] WeatherAccuracyPct { get; init; } = [];

    public int[] WeatherAirOps { get; init; } = [];

    /// <summary>SIM-11: thermal sights' minimum detection share, and the conditions whose penalties they cancel.</summary>
    public int ThermalOpticsPct { get; init; } = 100;

    public bool[] ThermalIgnores { get; init; } = [];

    /// <summary>MEC-07 time of day: optics and accuracy multipliers per step (dawn, day, dusk, night).</summary>
    public int[] TodOpticsPct { get; init; } = [100];

    public int[] TodAccuracyPct { get; init; } = [100];

    /// <summary>MEC-12: metres the loser's entry point falls back after an operation phase.</summary>
    public int OpSpawnPullbackM { get; init; }

    public const int TodNight = 3;

    public int TickHz { get; init; } = 20;

    public int NavCellM { get; init; }

    public int ReplanTicks { get; init; }

    public int ArcFrontHalfDeg { get; init; }

    public int AirAltitudeM { get; init; }

    public int ShooterMovingPct { get; init; }

    public int TargetMovingPct { get; init; }

    public int TurretJamHalfDeg { get; init; }

    public int NonpenSuppression { get; init; }

    public int NonpenMinorCritPct { get; init; }

    public int CritBasePct { get; init; }

    public int CritPer100MmPct { get; init; }

    /// <summary>Weights in order tracked, optics, engine, turret, bail, fire.</summary>
    public int[] CritWeights { get; init; } = [];

    public int FireHpPerTick { get; init; }

    public int[] VetAccuracyPct { get; init; } = [];

    public int[] VetKills { get; init; } = [];

    /// <summary>MEC-08: extra hit chance (percent) for a player-flown aircraft. Zero by design.</summary>
    public int DirectControlHitPct { get; init; }

    /// <summary>SUP-03 mines: hp per vehicle strike, density lost per strike.</summary>
    public int MineDamage { get; init; }

    public int MineDepletePct { get; init; }

    /// <summary>SUP-04: hit-chance multipliers under radar jamming and decoys; fire-mission delay under comms jamming.</summary>
    public int JamRadarPct { get; init; }

    public int DecoyPct { get; init; }

    public int JamCommsDelayTicks { get; init; }

    public int EscortPct { get; init; }

    /// <summary>SUP-01/04: GPS-jam CEP multiplier; FPV strike success, and under comms jamming.</summary>
    public int GpsJamCepX { get; init; }

    public int FpvSuccessPct { get; init; }

    public int FpvJammedPct { get; init; }

    public int CoverLightPct { get; init; } = 100;

    public int CoverHeavyPct { get; init; } = 100;

    public int CoverObjectM { get; init; }

    public int CraterMinBlastM { get; init; }

    public int CraterMax { get; init; }

    public int RevealOnFireTicks { get; init; }

    public int SuppressionMax { get; init; }

    public int DecayPerTick { get; init; }

    public int HqDecayBonus { get; init; }

    public int HqRadiusM { get; init; }

    public int ShakenAt { get; init; }

    public int PinnedAt { get; init; }

    public int RoutedAt { get; init; }

    public int RecoverMargin { get; init; }

    public int[] MoraleAccuracyPct { get; init; } = [];

    public int SurrenderEnemyM { get; init; }

    public int SurrenderAfterTicks { get; init; }

    public int CasualtySuppression { get; init; }

    public static readonly string[] Crits = ["tracked", "optics", "engine", "turret", "bail", "fire"];

    public int SupplyRadiusM { get; init; }

    public int AmmoIntervalTicks { get; init; }

    public int FuelPerTick { get; init; }

    public int FuelPerSupplyPoint { get; init; }

    public int AircraftTurnaroundTicks { get; init; }

    public int BingoFuelPct { get; init; }

    public int[] PhaseTicks { get; init; } = [];

    public int StartDp { get; init; }

    /// <summary>[profile][phase] deployment points per minute; profiles in IncomeProfiles order.</summary>
    public int[][] IncomePerMinute { get; init; } = [];

    public int SpKillPct { get; init; }

    public int SpSpotAssistPct { get; init; }

    /// <summary>MEC-06: ticks before an XO-run player's Field Requests offer is taken for it.</summary>
    public int FieldRequestAutoTicks { get; init; }

    public int SpPerSupplyPoints { get; init; }

    public static readonly string[] IncomeProfiles = ["vanguard", "maverick", "balanced", "juggernaut"];

    public static int ProfileIndex(string name)
    {
        var i = Array.IndexOf(IncomeProfiles, name);
        return i >= 0 ? i : throw new InvalidDataException($"Unknown income profile {name}.");
    }

    public int FrontCellM { get; init; }

    public int FrontUpdateTicks { get; init; }

    public int FrontRadiusM { get; init; }

    public int FrontFlipMargin { get; init; }

    /// <summary>Indexed by UnitDef.Kind (0 unused).</summary>
    public int[] FrontWeightByKind { get; init; } = [];

    public int FireSetupTicks { get; init; }

    public int SmokeRadiusM { get; init; }

    public int SmokeTicks { get; init; }

    public int MaxPendingRounds { get; init; }

    public int CbLocateTicks { get; init; }

    public int CbErrorM { get; init; }

    public int IllumRadiusM { get; init; }

    public int IllumTicks { get; init; }

    public CommandRules Command { get; init; } = new();

    public int VictoryPointsPerMinute { get; init; }

    public int WinPoints { get; init; }

    /// <summary>MODE-01 annihilation victory: checked from this tick of the operation on.</summary>
    public int AnnihilationGraceTicks { get; init; }

    public int TimeCapTicks { get; init; }

    public int ChunkM { get; init; }

    public int FloorDm { get; init; }

    public int CollapseDelayTicks { get; init; }

    public int FallDamage { get; init; }

    public int RubbleDmPerChunk { get; init; }

    public int[] MaterialHp { get; init; } = [];

    public int[] MaterialArmor { get; init; } = [];

    public static readonly string[] Materials = ["brick", "concrete", "timber", "plaster"];

    public static int MaterialIndex(string name)
    {
        var i = Array.IndexOf(Materials, name);
        return i >= 0 ? i : throw new InvalidDataException($"Unknown material {name}.");
    }

    /// <summary>Indexed [class][surface]: class 0 tracked, 1 wheeled, 2 infantry; surface 0 open, 1 road, 2 forest, 3 rubble. Cost 0 = impassable.</summary>
    public int[][] CostPct { get; init; } = [];

    public int[][] SpeedPct { get; init; } = [];

    /// <summary>MEC-09: ticks a carried infantry team stays on foot after its last fire, hit or suppression.</summary>
    public int DismountTicks { get; init; }

    /// <summary>SUP-03: ticks per hp a recovery vehicle restores, and ticks of repair to fix one critical.</summary>
    public int RepairIntervalTicks { get; init; }

    public int RepairCritTicks { get; init; }

    /// <summary>SUP-03: ticks per wounded soldier returned by medevac; supply points per tick a dump reloads a truck.</summary>
    public int MedevacTicks { get; init; }

    public int DumpRefillPerTick { get; init; }

    public int[] MaxSlopePct { get; init; } = [];

    public static readonly string[] MoveClasses = ["tracked", "wheeled", "infantry"];

    /// <summary>The highest optics percentage weather and time of day can combine to (their product, since DetectRange
    /// multiplies them) or a thermal sight allows, at least 100: the
    /// bound Sight.Spot uses to skip pairs beyond any possible detection range.</summary>
    public int MaxOpticsPct => _maxOpticsPct ??= Math.Max(
        Math.Max(100, ThermalOpticsPct),
        (WeatherOpticsPct.Count == 0 ? 100 : Math.Max(100, WeatherOpticsPct.Values.Max())) * (TodOpticsPct.Length == 0 ? 100 : Math.Max(100, TodOpticsPct.Max())) / 100);

    int? _maxOpticsPct;

    /// <summary>Rules that Sight.Spot's range bound relies on must not be negative (D073).</summary>
    internal static int NonNegative(int v, string name) => v >= 0 ? v : throw new InvalidDataException($"{name} must be >= 0, got {v}");

    public static readonly string[] WeatherNames = ["clear", "overcast", "rain", "fog", "snow", "night"];

    public int WeatherPct(int weather) =>
        weather >= 0 && weather < WeatherNames.Length && WeatherOpticsPct.TryGetValue(WeatherNames[weather], out var pct) ? pct : 100;

    /// <summary>True when aircraft may fly in the battle's weather.</summary>
    public bool AirOps(int weather) => weather < 0 || weather >= WeatherAirOps.Length || WeatherAirOps[weather] != 0;

    public static int WeatherIndex(string name)
    {
        var i = Array.IndexOf(WeatherNames, name);
        return i >= 0 ? i : throw new InvalidDataException($"Unknown weather {name}.");
    }

    public static BattleRules Load(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllBytes(path));
        var root = doc.RootElement;
        var los = root.GetProperty("los");
        var detect = root.GetProperty("detect");
        var weather = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var p in root.GetProperty("weather_optics_pct").EnumerateObject())
        {
            weather[p.Name] = p.Value.GetInt32();
        }

        var move = root.GetProperty("move");
        int[] ByClass(string name) => MoveClasses.Select(c => move.GetProperty(name).GetProperty(c).GetInt32()).ToArray();
        int[][] ByClassTerrain(string prefix) =>
            MoveClasses.Select((c, ci) => new[] { "open", "road", "forest", "rubble" }.Select(t => move.GetProperty($"{prefix}_{t}").GetProperty(c).GetInt32()).ToArray()).ToArray();

        var cb = root.GetProperty("combat");
        var mo = root.GetProperty("morale");
        int[] Arr(JsonElement e, string n) => e.GetProperty(n).EnumerateArray().Select(x => x.GetInt32()).ToArray();
        var st = root.GetProperty("structure");
        var mats = st.GetProperty("materials");

        return new BattleRules
        {
            ArcFrontHalfDeg = cb.GetProperty("arc_front_half_deg").GetInt32(),
            AirAltitudeM = cb.GetProperty("air_altitude_m").GetInt32(),
            ShooterMovingPct = cb.GetProperty("shooter_moving_pct").GetInt32(),
            TargetMovingPct = cb.GetProperty("target_moving_pct").GetInt32(),
            TurretJamHalfDeg = cb.GetProperty("turret_jam_half_deg").GetInt32(),
            NonpenSuppression = cb.GetProperty("nonpen_suppression").GetInt32(),
            NonpenMinorCritPct = cb.GetProperty("nonpen_minor_crit_pct").GetInt32(),
            CritBasePct = cb.GetProperty("crit_base_pct").GetInt32(),
            CritPer100MmPct = cb.GetProperty("crit_per_100mm_overmatch_pct").GetInt32(),
            CritWeights = Crits.Select(c => cb.GetProperty("crit_weights").GetProperty(c).GetInt32()).ToArray(),
            FireHpPerTick = cb.GetProperty("fire_hp_per_tick").GetInt32(),
            VetAccuracyPct = Arr(cb, "vet_accuracy_pct"),
            VetKills = Arr(cb, "vet_kills"),
            CoverLightPct = cb.GetProperty("cover_light_pct").GetInt32(),
            CoverHeavyPct = cb.GetProperty("cover_heavy_pct").GetInt32(),
            CoverObjectM = cb.GetProperty("cover_object_m").GetInt32(),
            CraterMinBlastM = cb.GetProperty("crater_min_blast_m").GetInt32(),
            CraterMax = cb.GetProperty("crater_max").GetInt32(),
            RevealOnFireTicks = cb.GetProperty("reveal_on_fire_ticks").GetInt32(),
            DirectControlHitPct = cb.GetProperty("direct_control_hit_pct").GetInt32(),
            MineDamage = cb.GetProperty("mine_damage").GetInt32(),
            MineDepletePct = cb.GetProperty("mine_deplete_pct").GetInt32(),
            JamRadarPct = cb.GetProperty("jam_radar_pct").GetInt32(),
            DecoyPct = cb.GetProperty("decoy_pct").GetInt32(),
            JamCommsDelayTicks = cb.GetProperty("jam_comms_delay_ticks").GetInt32(),
            EscortPct = cb.GetProperty("escort_pct").GetInt32(),
            GpsJamCepX = cb.GetProperty("gps_jam_cep_x").GetInt32(),
            FpvSuccessPct = cb.GetProperty("fpv_success_pct").GetInt32(),
            FpvJammedPct = cb.GetProperty("fpv_jammed_pct").GetInt32(),
            SuppressionMax = mo.GetProperty("suppression_max").GetInt32(),
            DecayPerTick = mo.GetProperty("decay_per_tick").GetInt32(),
            HqDecayBonus = mo.GetProperty("hq_decay_bonus").GetInt32(),
            HqRadiusM = mo.GetProperty("hq_radius_m").GetInt32(),
            ShakenAt = mo.GetProperty("shaken_at").GetInt32(),
            PinnedAt = mo.GetProperty("pinned_at").GetInt32(),
            RoutedAt = mo.GetProperty("routed_at").GetInt32(),
            RecoverMargin = mo.GetProperty("recover_margin").GetInt32(),
            MoraleAccuracyPct = Arr(mo, "accuracy_pct"),
            SurrenderEnemyM = mo.GetProperty("surrender_enemy_m").GetInt32(),
            SurrenderAfterTicks = mo.GetProperty("surrender_after_ticks").GetInt32(),
            CasualtySuppression = mo.GetProperty("casualty_suppression").GetInt32(),
            SupplyRadiusM = root.GetProperty("supply").GetProperty("radius_m").GetInt32(),
            AmmoIntervalTicks = root.GetProperty("supply").GetProperty("ammo_interval_ticks").GetInt32(),
            FuelPerTick = root.GetProperty("supply").GetProperty("fuel_per_tick").GetInt32(),
            FuelPerSupplyPoint = root.GetProperty("supply").GetProperty("fuel_per_supply_point").GetInt32(),
            RepairIntervalTicks = root.GetProperty("supply").GetProperty("repair_interval_ticks").GetInt32(),
            RepairCritTicks = root.GetProperty("supply").GetProperty("repair_crit_ticks").GetInt32(),
            MedevacTicks = root.GetProperty("supply").GetProperty("medevac_ticks").GetInt32(),
            DumpRefillPerTick = root.GetProperty("supply").GetProperty("dump_refill_per_tick").GetInt32(),
            AircraftTurnaroundTicks = root.GetProperty("supply").GetProperty("aircraft_turnaround_ticks").GetInt32(),
            BingoFuelPct = root.GetProperty("supply").GetProperty("bingo_fuel_pct").GetInt32(),
            PhaseTicks = Arr(root.GetProperty("economy"), "phase_ticks"),
            StartDp = root.GetProperty("economy").GetProperty("start_dp").GetInt32(),
            IncomePerMinute = IncomeProfiles.Select(pr => root.GetProperty("economy").GetProperty("income_per_minute").GetProperty(pr).EnumerateArray().Select(x => x.GetInt32()).ToArray()).ToArray(),
            SpKillPct = root.GetProperty("economy").GetProperty("sp_kill_pct").GetInt32(),
            SpSpotAssistPct = root.GetProperty("economy").GetProperty("sp_spot_assist_pct").GetInt32(),
            FieldRequestAutoTicks = root.GetProperty("economy").GetProperty("field_request_auto_ticks").GetInt32(),
            SpPerSupplyPoints = root.GetProperty("economy").GetProperty("sp_per_supply_points").GetInt32(),
            FrontCellM = root.GetProperty("frontline").GetProperty("cell_m").GetInt32(),
            FrontUpdateTicks = root.GetProperty("frontline").GetProperty("update_ticks").GetInt32(),
            FrontRadiusM = root.GetProperty("frontline").GetProperty("radius_m").GetInt32(),
            FrontFlipMargin = root.GetProperty("frontline").GetProperty("flip_margin").GetInt32(),
            FrontWeightByKind = new[] { "", "infantry", "tank", "ifv", "artillery", "aa", "air", "supply", "command" }
                .Select(k => k.Length == 0 ? 0 : root.GetProperty("frontline").GetProperty("weight_by_kind").GetProperty(k).GetInt32()).ToArray(),
            FireSetupTicks = root.GetProperty("fires").GetProperty("setup_ticks").GetInt32(),
            SmokeRadiusM = root.GetProperty("fires").GetProperty("smoke_radius_m").GetInt32(),
            SmokeTicks = root.GetProperty("fires").GetProperty("smoke_ticks").GetInt32(),
            MaxPendingRounds = root.GetProperty("fires").GetProperty("max_pending").GetInt32(),
            CbLocateTicks = root.GetProperty("fires").GetProperty("cb_locate_ticks").GetInt32(),
            CbErrorM = root.GetProperty("fires").GetProperty("cb_error_m").GetInt32(),
            IllumRadiusM = root.GetProperty("fires").GetProperty("illum_radius_m").GetInt32(),
            IllumTicks = root.GetProperty("fires").GetProperty("illum_ticks").GetInt32(),
            Command = CommandRules.From(root.GetProperty("command")),
            VictoryPointsPerMinute = root.GetProperty("victory").GetProperty("points_per_minute").GetInt32(),
            WinPoints = root.GetProperty("victory").GetProperty("win_points").GetInt32(),
            AnnihilationGraceTicks = root.GetProperty("victory").GetProperty("annihilation_grace_ticks").GetInt32(),
            TimeCapTicks = root.GetProperty("victory").GetProperty("time_cap_ticks").GetInt32(),
            ChunkM = st.GetProperty("chunk_m").GetInt32(),
            FloorDm = st.GetProperty("floor_dm").GetInt32(),
            CollapseDelayTicks = st.GetProperty("collapse_delay_ticks").GetInt32(),
            FallDamage = st.GetProperty("fall_damage").GetInt32(),
            RubbleDmPerChunk = st.GetProperty("rubble_dm_per_chunk").GetInt32(),
            MaterialHp = Materials.Select(m => mats.GetProperty(m).GetProperty("hp").GetInt32()).ToArray(),
            MaterialArmor = Materials.Select(m => mats.GetProperty(m).GetProperty("armor").GetInt32()).ToArray(),
            TickHz = root.GetProperty("tick_hz").GetInt32(),
            NavCellM = move.GetProperty("nav_cell_m").GetInt32(),
            ReplanTicks = move.GetProperty("replan_ticks").GetInt32(),
            DismountTicks = move.GetProperty("dismount_ticks").GetInt32(),
            CostPct = ByClassTerrain("cost"),
            SpeedPct = ByClassTerrain("speed"),
            MaxSlopePct = ByClass("max_slope_pct"),
            LosStepM = los.GetProperty("step_m").GetInt32(),
            EyeHeightDm = los.GetProperty("eye_height_dm").GetInt32(),
            TargetHeightDm = los.GetProperty("target_height_dm").GetInt32(),
            ForestHeightDm = los.GetProperty("forest_height_dm").GetInt32(),
            ForestBlockPctM = los.GetProperty("forest_block_pct_m").GetInt32(),
            SmokeHeightDm = los.GetProperty("smoke_height_dm").GetInt32(),
            HedgeHeightDm = los.GetProperty("hedge_height_dm").GetInt32(),
            StealthForestBonus = NonNegative(detect.GetProperty("stealth_forest_bonus").GetInt32(), "detection.stealth_forest_bonus"),
            StealthMovingPenalty = NonNegative(detect.GetProperty("stealth_moving_penalty").GetInt32(), "detection.stealth_moving_penalty"),
            FiringRevealM = detect.GetProperty("firing_reveal_m").GetInt32(),
            RevealTicks = detect.GetProperty("reveal_ticks").GetInt32(),
            SpotIntervalTicks = detect.GetProperty("spot_interval_ticks").GetInt32(),
            WeatherOpticsPct = weather,
            WeatherAccuracyPct = WeatherNames.Select(n => root.GetProperty("weather_accuracy_pct").GetProperty(n).GetInt32()).ToArray(),
            WeatherAirOps = WeatherNames.Select(n => root.GetProperty("weather_air_ops").GetProperty(n).GetInt32()).ToArray(),
            ThermalOpticsPct = root.GetProperty("thermal").GetProperty("optics_pct").GetInt32(),
            TodOpticsPct = root.GetProperty("time_of_day").GetProperty("optics_pct").EnumerateArray().Select(x => x.GetInt32()).ToArray(),
            TodAccuracyPct = root.GetProperty("time_of_day").GetProperty("accuracy_pct").EnumerateArray().Select(x => x.GetInt32()).ToArray(),
            OpSpawnPullbackM = root.GetProperty("operation").GetProperty("spawn_pullback_m").GetInt32(),
            ThermalIgnores = WeatherNames.Select(n => root.GetProperty("thermal").GetProperty("ignores").EnumerateArray().Any(x => x.GetString() == n)).ToArray(),
        };
    }
}

/// <summary>Command planner tuning (data/rules.json "command").</summary>
public sealed class CommandRules
{
    public int PlanTicks { get; init; } = 20;

    public int AssemblePct { get; init; }

    public int AssembleRadiusM { get; init; }

    public int AssembleTimeoutTicks { get; init; }

    public int StagingDistanceM { get; init; }

    public int PrepWaitTicks { get; init; }

    public int PrepRounds { get; init; }

    public int DamagedHpPct { get; init; }

    public int LowAmmoPct { get; init; }

    public int ObjectiveRadiusM { get; init; }

    public int FailStrengthPct { get; init; }

    public int DefendSpacingM { get; init; }

    public int CoverSearchM { get; init; }

    public int FormationSpacingM { get; init; }

    public int CasOnStationM { get; init; }

    public int CasLoiterTicks { get; init; }

    public int CapOrbitM { get; init; }

    public int CapLegTicks { get; init; }

    public int ScreenWithdrawM { get; init; }

    public int CasThreatMarginM { get; init; }

    public int PriorityTargetPct { get; init; } = 100;

    public int PlannerPrepTicks { get; init; }

    public int PlannerPrepBonusPct { get; init; }

    public int PlannerMicroDecay { get; init; }

    public int PlannerGarrisonRadiusM { get; init; }

    public int ScreenContactTicks { get; init; }

    public static CommandRules From(JsonElement e) => new()
    {
        PlanTicks = e.GetProperty("plan_ticks").GetInt32(),
        AssemblePct = e.GetProperty("assemble_pct").GetInt32(),
        AssembleRadiusM = e.GetProperty("assemble_radius_m").GetInt32(),
        AssembleTimeoutTicks = e.GetProperty("assemble_timeout_ticks").GetInt32(),
        StagingDistanceM = e.GetProperty("staging_distance_m").GetInt32(),
        PrepWaitTicks = e.GetProperty("prep_wait_ticks").GetInt32(),
        PrepRounds = e.GetProperty("prep_rounds").GetInt32(),
        DamagedHpPct = e.GetProperty("damaged_hp_pct").GetInt32(),
        LowAmmoPct = e.GetProperty("low_ammo_pct").GetInt32(),
        ObjectiveRadiusM = e.GetProperty("objective_radius_m").GetInt32(),
        FailStrengthPct = e.GetProperty("fail_strength_pct").GetInt32(),
        DefendSpacingM = e.GetProperty("defend_spacing_m").GetInt32(),
        CoverSearchM = e.GetProperty("cover_search_m").GetInt32(),
        FormationSpacingM = e.GetProperty("formation_spacing_m").GetInt32(),
        CasOnStationM = e.GetProperty("cas_on_station_m").GetInt32(),
        CasLoiterTicks = e.GetProperty("cas_loiter_ticks").GetInt32(),
        CapOrbitM = e.GetProperty("cap_orbit_m").GetInt32(),
        CapLegTicks = e.GetProperty("cap_leg_ticks").GetInt32(),
        ScreenWithdrawM = e.GetProperty("screen_withdraw_m").GetInt32(),
        CasThreatMarginM = e.GetProperty("cas_threat_margin_m").GetInt32(),
        PriorityTargetPct = e.GetProperty("priority_target_pct").GetInt32(),
        PlannerPrepTicks = e.GetProperty("planner_prep_ticks").GetInt32(),
        PlannerPrepBonusPct = e.GetProperty("planner_prep_bonus_pct").GetInt32(),
        PlannerMicroDecay = e.GetProperty("planner_micro_decay").GetInt32(),
        PlannerGarrisonRadiusM = e.GetProperty("planner_garrison_radius_m").GetInt32(),
        ScreenContactTicks = e.GetProperty("screen_contact_ticks").GetInt32(),
    };
}

